// NOTE: this should work as long as the delegate graph's implementation of edges() (like that of
// AbstractGraph) derives its behavior from calling successors().
private static final class TransposedGraph<N> extends ForwardingGraph<N> {
  private final Graph<N> graph;

  TransposedGraph(Graph<N> graph) {
    this.graph = graph;
  }

  @Override
  Graph<N> delegate() {
    return graph;
  }

  @Override
  public Set<N> predecessors(N node) {
    return transposedPredecessors(graph, node);
  }

  @Override
  public Set<N> successors(N node) {
    return transposedSuccessors(graph, node);
  }

  @Override
  public Set<EndpointPair<N>> incidentEdges(N node) {
    return new IncidentEdgeSet<N>(this, node, IncidentEdgeSet.EdgeType.BOTH) {
      @Override
      public Iterator<EndpointPair<N>> iterator() {
        return transform(
            delegate().incidentEdges(node).iterator(),
            edge -> EndpointPair.of(delegate(), edge.nodeV(), edge.nodeU()));
      }
    };
  }

  @Override
  public int inDegree(N node) {
    return transposedInDegree(graph, node);
  }

  @Override
  public int outDegree(N node) {
    return transposedOutDegree(graph, node);
  }

  @Override
  public boolean hasEdgeConnecting(N nodeU, N nodeV) {
    return transposedHasEdgeConnecting(graph, nodeU, nodeV);
  }

  @Override
  public boolean hasEdgeConnecting(EndpointPair<N> endpoints) {
    return transposedHasEdgeConnecting(graph, endpoints);
  }
}

